        c4varysIdle: ['Las tormentas vienen y van, los peces grandes se comen a los pequeños, y yo sigo remando.'],
        c4jaimeIdle: ['No hay hombres como yo. Solo yo. Mantén la guardia alta.'],
        c4davosIdle: ['Un contrabandista de cebollas entre reyes. Alguien tiene que decir la verdad sencilla.'],
        c4brienneIdle: ['Un juramento es un juramento. Juré proteger a los inocentes.'],
        c4melisandreIdle: ['La noche es oscura y alberga horrores... pero el fuego los consume todos.'],
        c4daenerysIdle: ['El fuego no puede matar a un dragón. Y el invierno no reclamará este mundo mientras estemos unidos.'],
        c4jorahIdle: ['El acero valyrio y el temple norteño te llevarán a la victoria.'],
        c4jaqenIdle: ['Valar Morghulis. Un héroe tiene muchos nombres y muchos rostros.'],
        c4jonIdle: ['Somos los vigilantes del Muro. El escudo que defiende los reinos de los hombres.'],
        c4samwellIdle: ['¡Lo leí en un libro antiguo de la Ciudadela! ¡Vidriagón y acero valyrio, nunca lo olvides!'],
        c4aemonIdle: ['Cuatro Crónicas de los Maestres se perdieron por Poniente y Essos. Léelas todas para mí.'],
        c4aemonDone: ['¡Encontraste las cuatro Crónicas! La historia del reino está completa.', 'Toma esta espada: Colmillo del Invierno, forjada en verdadero acero valyrio. Que te sirva contra el Rey de la Noche.'],
        c4manceIdle: ['No nos arrodillamos Más Allá del Muro, pero luchamos junto a cualquiera lo bastante valiente.'],
        c4childIdle: ['Cantábamos la canción de la tierra mucho antes de los Primeros Hombres. Ahora cantamos contigo.'],
        c4gendry: ['Forjé martillos de guerra en el Lecho de Pulgas. ¡Tráeme mineral y oro!'],
        c4qyburn: ['Leche de amapola y elixires restauradores. Bebe, amigo mío.'],
        c4scoutIdle: ['¡Gracias a los Antiguos Dioses! Regresaré a informar a Invernalia.'],
        c4folk1: ['Leones, lobos, ciervos y dragones... el pueblo solo reza para que sobreviva la cosecha.'],
        c4folk2: ['En Braavos, el Banco de Hierro siempre cobra su deuda.'],
        c4folkLit: ['¡Las Almenaras arden! ¡La Larga Noche por fin ha sido rota!'],
        c4ally_stark: ['¡El Norte está contigo! ¡Los mejores de Invernalia cubren tu espalda!'],
        c4ally_baratheon: ['¡Nuestra es la furia! ¡Golpea como la tormenta!'],
